'use client'

import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  useState,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from 'react'
import {
  TESTIMONIALS,
  TestimonialCard,
  TestimonialsButton,
  TestimonialsContainer,
  TestimonialsHeader,
  TestimonialsSection,
  type Testimonial,
} from '@/components/blocks/social-proof/testimonials'
import { cn } from '@/lib/utils'

const REVEAL_STAGGER_MS = 60

export interface SocialProofTestimonialsProps extends Omit<
  ComponentPropsWithoutRef<'section'>,
  'title'
> {
  title?: ReactNode
  description?: ReactNode
  testimonials?: Testimonial[]
  initialCount?: number
  showMoreLabel?: string
  showLessLabel?: string
}

export const SocialProofTestimonials = forwardRef<HTMLElement, SocialProofTestimonialsProps>(
  (
    {
      title = 'What teams say',
      description = 'Notes from people shipping real products with Nexvyn UI.',
      testimonials = TESTIMONIALS,
      initialCount = 3,
      showMoreLabel = 'Show more',
      showLessLabel = 'Show less',
      ...props
    },
    ref,
  ) => {
    const headingId = useId()
    const listId = useId()
    const [expanded, setExpanded] = useState(false)
    const buttonRef = useRef<HTMLButtonElement>(null)
    const collapsedByUser = useRef(false)
    const collapsible = testimonials.length > initialCount

    useEffect(() => {
      if (expanded || !collapsedByUser.current) return
      collapsedByUser.current = false
      buttonRef.current?.scrollIntoView({ block: 'nearest' })
    }, [expanded])

    const toggle = () => {
      collapsedByUser.current = expanded
      setExpanded((value) => !value)
    }

    return (
      <TestimonialsSection ref={ref} labelledBy={headingId} {...props}>
        <TestimonialsContainer>
          <TestimonialsHeader id={headingId} title={title} description={description} />
          <ul
            id={listId}
            className={cn(
              'mt-12 columns-1 gap-4 md:columns-2 lg:columns-3',
              collapsible &&
                !expanded &&
                'mask-[linear-gradient(to_bottom,black_60%,transparent)] md:mask-none',
            )}
          >
            {testimonials.map((testimonial, index) => {
              const extra = index >= initialCount
              const revealed = extra && expanded
              return (
                <li
                  key={`${testimonial.name}-${index}`}
                  className={cn(
                    'mb-4 break-inside-avoid',
                    extra && !expanded && 'hidden md:block',
                    revealed &&
                      'transition-[opacity,translate] duration-(--motion-dur-slow) ease-(--motion-ease-out) starting:translate-y-2 starting:opacity-0 motion-reduce:transition-none',
                  )}
                  style={
                    revealed
                      ? { transitionDelay: `${(index - initialCount) * REVEAL_STAGGER_MS}ms` }
                      : undefined
                  }
                >
                  <TestimonialCard testimonial={testimonial} />
                </li>
              )
            })}
          </ul>
          {collapsible && (
            <TestimonialsButton
              ref={buttonRef}
              aria-expanded={expanded}
              aria-controls={listId}
              onClick={toggle}
              className="mt-2 w-full md:hidden"
            >
              {expanded ? showLessLabel : showMoreLabel}
            </TestimonialsButton>
          )}
        </TestimonialsContainer>
      </TestimonialsSection>
    )
  },
)
SocialProofTestimonials.displayName = 'SocialProofTestimonials'

'use client'

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import { NameAvatar } from '@/components/blocks/shared/name-avatar'
import { cn } from '@/lib/utils'

export type Testimonial = { quote: string; name: string; role: string }

export const TESTIMONIALS: Testimonial[] = [
  {
    quote:
      'We copied the dialog source into our repo and changed two tokens. It matched the rest of our product on the first try, in both themes.',
    name: 'Ruth Abara',
    role: 'Frontend lead, Quillfern',
  },
  {
    quote:
      'Keyboard support is the part I usually rebuild by hand. Arrow keys, Escape and focus return already worked, so I spent the week on our actual product.',
    name: 'Tomas Lindqvist',
    role: 'Design engineer, Pellmark',
  },
  {
    quote:
      'I am not a designer and our marketing site still looks calm. Dark mode came along for free because everything reads from tokens.',
    name: 'Amara Osei',
    role: 'Founder, Tindra',
  },
  {
    quote:
      'Reviews got shorter. It is plain React and Tailwind, so nobody had to learn a new library to read the diff.',
    name: 'Daniel Ferreira',
    role: 'Engineering manager, Mossline',
  },
  {
    quote:
      'The motion is quiet and it already respects reduced motion. Our accessibility audit came back with notes on our own code, not on these parts.',
    name: 'Lena Hoffmann',
    role: 'Product designer, Harrowgate Bikes',
  },
  {
    quote:
      'I needed a pricing section and a login by Friday. Two blocks, one afternoon, and the source is mine to change.',
    name: 'Sam Okoro',
    role: 'Solo developer, Ostrander Print',
  },
]

export const TestimonialsSection = forwardRef<
  HTMLElement,
  ComponentPropsWithoutRef<'section'> & { labelledBy: string }
>(({ labelledBy, className, ...props }, ref) => (
  <section
    ref={ref}
    aria-labelledby={labelledBy}
    className={cn('w-full bg-(--color-bg) py-16 md:py-24', className)}
    {...props}
  />
))
TestimonialsSection.displayName = 'TestimonialsSection'

export function TestimonialsContainer({
  className,
  children,
}: {
  className?: string
  children: ReactNode
}) {
  return <div className={cn('mx-auto w-full max-w-5xl px-6 sm:px-8', className)}>{children}</div>
}

export function TestimonialsHeader({
  id,
  title,
  description,
}: {
  id: string
  title: ReactNode
  description?: ReactNode
}) {
  return (
    <div className="flex max-w-md flex-col gap-3">
      <h2
        id={id}
        className="text-balance text-2xl font-normal tracking-tight text-(--color-fg) md:text-3xl"
      >
        {title}
      </h2>
      {description && (
        <p className="text-pretty text-sm text-(--color-muted) md:text-base">{description}</p>
      )}
    </div>
  )
}

export interface TestimonialCardProps extends ComponentPropsWithoutRef<'figure'> {
  testimonial: Testimonial
}

export const TestimonialCard = forwardRef<HTMLElement, TestimonialCardProps>(
  ({ testimonial, className, ...props }, ref) => (
    <figure
      ref={ref}
      className={cn('flex flex-col gap-6 rounded-md bg-(--color-surface) p-6', className)}
      {...props}
    >
      <blockquote className="text-pretty text-sm leading-relaxed text-(--color-fg) md:text-base">
        <p>{testimonial.quote}</p>
      </blockquote>
      <figcaption className="mt-auto flex items-center gap-3">
        <NameAvatar name={testimonial.name} />
        <span className="flex min-w-0 flex-col">
          <span className="text-sm text-(--color-fg)">{testimonial.name}</span>
          <span className="text-xs text-(--color-muted)">{testimonial.role}</span>
        </span>
      </figcaption>
    </figure>
  ),
)
TestimonialCard.displayName = 'TestimonialCard'

export const TestimonialsButton = forwardRef<HTMLButtonElement, ComponentPropsWithoutRef<'button'>>(
  ({ className, type = 'button', ...props }, ref) => (
    <button
      ref={ref}
      type={type}
      className={cn(
        'inline-flex h-11 items-center justify-center rounded-md border border-(--color-border) px-5 text-sm text-(--color-fg) transition-[background-color,border-color,scale] duration-(--motion-dur-fast) ease hover:border-(--color-border-strong) hover:bg-(--color-fg)/5 active:scale-[0.97] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) motion-reduce:transition-none motion-reduce:active:scale-100',
        className,
      )}
      {...props}
    />
  ),
)
TestimonialsButton.displayName = 'TestimonialsButton'

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import { cn } from '@/lib/utils'

export interface NameAvatarProps extends Omit<ComponentPropsWithoutRef<'span'>, 'children'> {
  name: string
  size?: number
}

const STRONG = 'fill-current text-(--color-fg)/70'
const MID = 'fill-current text-(--color-fg)/40'
const SOFT = 'fill-current text-(--color-fg)/20'

function hashName(value: string) {
  let hash = 2166136261
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i)
    hash = Math.imul(hash, 16777619)
  }
  hash ^= hash >>> 16
  hash = Math.imul(hash, 2246822507)
  hash ^= hash >>> 13
  hash = Math.imul(hash, 3266489909)
  hash ^= hash >>> 16
  return hash >>> 0
}

function shapes(seed: number): ReactNode {
  const nudge = (((seed >>> 16) % 3) - 1) * 2
  switch ((seed >>> 8) % 3) {
    case 0:
      return (
        <>
          <circle cx={13} cy={14} r={10} className={SOFT} />
          <circle cx={22 + nudge} cy={21} r={4.5} className={STRONG} />
        </>
      )
    case 1:
      return (
        <>
          <path d="M4 18 A12 12 0 0 0 28 18 Z" className={SOFT} />
          <circle cx={16 + nudge} cy={11} r={4} className={STRONG} />
        </>
      )
    default:
      return (
        <>
          <rect x={6} y={9} width={20} height={6} rx={3} className={SOFT} />
          <rect x={6} y={17} width={14 + nudge} height={6} rx={3} className={MID} />
          <circle cx={25} cy={20} r={3} className={STRONG} />
        </>
      )
  }
}

export const NameAvatar = forwardRef<HTMLSpanElement, NameAvatarProps>(
  ({ name, size = 32, className, style, ...props }, ref) => {
    const seed = hashName(name.trim().toLowerCase())
    const rotation = (seed & 7) * 45

    return (
      <span
        ref={ref}
        className={cn(
          'squircle relative inline-flex shrink-0 overflow-hidden bg-(--color-surface-2)',
          className,
        )}
        style={{ width: size, height: size, ...style }}
        {...props}
      >
        <svg
          aria-hidden="true"
          focusable="false"
          viewBox="0 0 32 32"
          width={size}
          height={size}
          fill="currentColor"
          className="block"
        >
          <g transform={`rotate(${rotation} 16 16)`}>{shapes(seed)}</g>
        </svg>
      </span>
    )
  },
)
NameAvatar.displayName = 'NameAvatar'
